import{_ as a,o as t,c as o,a2 as i}from"./chunks/framework.D7WGirly.js";const u=JSON.parse('{"title":"Lodestone API & MCP — Troubleshooting & FAQs","description":"","frontmatter":{},"headers":[],"relativePath":"api-04-troubleshooting-and-faqs.md","filePath":"api-04-troubleshooting-and-faqs.md"}'),n={name:"api-04-troubleshooting-and-faqs.md"};function r(s,e,h,d,l,p){return t(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="lodestone-api-mcp-—-troubleshooting-faqs" tabindex="-1">Lodestone API &amp; MCP — Troubleshooting &amp; FAQs <a class="header-anchor" href="#lodestone-api-mcp-—-troubleshooting-faqs" aria-label="Permalink to &quot;Lodestone API &amp; MCP — Troubleshooting &amp; FAQs&quot;">​</a></h1><p><em>Common authentication issues, scope errors, and answers to frequent questions</em></p><hr><h2 id="frequently-asked-questions" tabindex="-1">Frequently Asked Questions <a class="header-anchor" href="#frequently-asked-questions" aria-label="Permalink to &quot;Frequently Asked Questions&quot;">​</a></h2><h3 id="who-can-generate-api-keys" tabindex="-1">Who can generate API keys? <a class="header-anchor" href="#who-can-generate-api-keys" aria-label="Permalink to &quot;Who can generate API keys?&quot;">​</a></h3><p>Any workspace member can generate API keys for their organization. Keys are scoped to an organization, not to an individual user — they provide access to the organization&#39;s data regardless of who created them.</p><h3 id="how-many-api-keys-can-i-have" tabindex="-1">How many API keys can I have? <a class="header-anchor" href="#how-many-api-keys-can-i-have" aria-label="Permalink to &quot;How many API keys can I have?&quot;">​</a></h3><p>There is no enforced limit. You can generate multiple keys with different scopes for different purposes, and revoke them individually.</p><h3 id="can-i-retrieve-the-full-api-key-after-it-s-been-created" tabindex="-1">Can I retrieve the full API key after it&#39;s been created? <a class="header-anchor" href="#can-i-retrieve-the-full-api-key-after-it-s-been-created" aria-label="Permalink to &quot;Can I retrieve the full API key after it&#39;s been created?&quot;">​</a></h3><p>No. The full key value is displayed <strong>once</strong> at the moment of creation. After you navigate away, only a masked prefix is shown. If you lose the key, revoke it and generate a new one.</p><h3 id="does-an-api-key-expire" tabindex="-1">Does an API key expire? <a class="header-anchor" href="#does-an-api-key-expire" aria-label="Permalink to &quot;Does an API key expire?&quot;">​</a></h3><p>API keys do not expire automatically. They remain valid until revoked. Revoking is immediate — any requests using a revoked key return <code>401 Unauthorized</code> at once.</p><h3 id="what-happens-to-requests-made-with-a-revoked-key" tabindex="-1">What happens to requests made with a revoked key? <a class="header-anchor" href="#what-happens-to-requests-made-with-a-revoked-key" aria-label="Permalink to &quot;What happens to requests made with a revoked key?&quot;">​</a></h3><p>They are rejected immediately with a <code>401 Unauthorized</code> response. There is no grace period.</p><h3 id="where-do-i-find-my-organization-id" tabindex="-1">Where do I find my Organization ID? <a class="header-anchor" href="#where-do-i-find-my-organization-id" aria-label="Permalink to &quot;Where do I find my Organization ID?&quot;">​</a></h3><p>Look at the URL when logged into Lodestone. The Organization ID is the alphanumeric string between <code>/organizations/</code> and the next <code>/</code> in the URL:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://app.lodestonepm.com/organizations/YOUR_ORG_ID/features</span></span></code></pre></div><h3 id="is-the-api-available-on-all-subscription-plans" tabindex="-1">Is the API available on all subscription plans? <a class="header-anchor" href="#is-the-api-available-on-all-subscription-plans" aria-label="Permalink to &quot;Is the API available on all subscription plans?&quot;">​</a></h3><p>Yes. The API is available to all Lodestone users — there are no plan or tier restrictions.</p><h3 id="can-the-api-delete-features" tabindex="-1">Can the API delete Features? <a class="header-anchor" href="#can-the-api-delete-features" aria-label="Permalink to &quot;Can the API delete Features?&quot;">​</a></h3><p>No. The current API does not expose delete operations for Features or other objects. Deletion must be performed from the Lodestone UI.</p><h3 id="what-is-the-base-url-for-all-api-requests" tabindex="-1">What is the base URL for all API requests? <a class="header-anchor" href="#what-is-the-base-url-for-all-api-requests" aria-label="Permalink to &quot;What is the base URL for all API requests?&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://app.lodestonepm.com/api/v1/</span></span></code></pre></div><h3 id="where-is-the-full-api-reference" tabindex="-1">Where is the full API reference? <a class="header-anchor" href="#where-is-the-full-api-reference" aria-label="Permalink to &quot;Where is the full API reference?&quot;">​</a></h3><p>The OpenAPI specification is available at: <code>https://app.lodestonepm.com/api/v1/openapi</code></p><hr><h2 id="common-issues" tabindex="-1">Common Issues <a class="header-anchor" href="#common-issues" aria-label="Permalink to &quot;Common Issues&quot;">​</a></h2><h3 id="requests-return-401-unauthorized" tabindex="-1">Requests return <code>401 Unauthorized</code> <a class="header-anchor" href="#requests-return-401-unauthorized" aria-label="Permalink to &quot;Requests return `401 Unauthorized`&quot;">​</a></h3><p>Check the following in order:</p><ol><li>Your request includes the <code>Authorization: Bearer YOUR_KEY</code> header</li><li>The key has not been revoked — check Settings &gt; Integrations to confirm it&#39;s still active</li><li>The key is for the correct organization — keys are org-scoped and won&#39;t work for a different org&#39;s endpoints</li><li>You&#39;re using the correct base URL (<code>https://app.lodestonepm.com/api/v1/</code>)</li></ol><h3 id="requests-return-403-forbidden" tabindex="-1">Requests return <code>403 Forbidden</code> <a class="header-anchor" href="#requests-return-403-forbidden" aria-label="Permalink to &quot;Requests return `403 Forbidden`&quot;">​</a></h3><p>This means your key doesn&#39;t have the scope required for the operation you&#39;re attempting. Check what scopes are needed for the endpoint (see the OpenAPI spec or the Scopes table in the Overview doc) and compare against the scopes assigned to your key. If the key is missing a scope, you&#39;ll need to revoke it and generate a new one with the correct scopes — scopes cannot be added to an existing key.</p><h3 id="my-ai-assistant-isn-t-finding-the-right-features-or-roadmaps" tabindex="-1">My AI assistant isn&#39;t finding the right Features or Roadmaps <a class="header-anchor" href="#my-ai-assistant-isn-t-finding-the-right-features-or-roadmaps" aria-label="Permalink to &quot;My AI assistant isn&#39;t finding the right Features or Roadmaps&quot;">​</a></h3><p>This is usually a context issue rather than an API issue. Check that:</p><ul><li>The <code>organizationId</code> parameter is correct — this is required for most list endpoints</li><li>The assistant&#39;s instructions specify which organization to query (without this, the assistant may not know which org to use)</li><li>The data you&#39;re looking for actually exists in Lodestone and hasn&#39;t been archived</li></ul><h3 id="the-openapi-spec-import-into-chatgpt-isn-t-working" tabindex="-1">The OpenAPI spec import into ChatGPT isn&#39;t working <a class="header-anchor" href="#the-openapi-spec-import-into-chatgpt-isn-t-working" aria-label="Permalink to &quot;The OpenAPI spec import into ChatGPT isn&#39;t working&quot;">​</a></h3><p>Try the following:</p><ul><li>Make sure you&#39;re importing from the URL <code>https://app.lodestonepm.com/api/v1/openapi</code> (not a local file)</li><li>Check that the GPT action is configured with Bearer token authentication</li><li>If ChatGPT shows an error during import, verify the URL is accessible and returns a valid JSON response</li></ul><h3 id="requests-return-429-too-many-requests" tabindex="-1">Requests return <code>429 Too Many Requests</code> <a class="header-anchor" href="#requests-return-429-too-many-requests" aria-label="Permalink to &quot;Requests return `429 Too Many Requests`&quot;">​</a></h3><p>You&#39;re hitting the rate limit. Add a delay between requests or spread batch operations over time. Implement exponential backoff in any automated script that retries failed requests.</p><h3 id="changes-made-via-api-aren-t-appearing-in-lodestone" tabindex="-1">Changes made via API aren&#39;t appearing in Lodestone <a class="header-anchor" href="#changes-made-via-api-aren-t-appearing-in-lodestone" aria-label="Permalink to &quot;Changes made via API aren&#39;t appearing in Lodestone&quot;">​</a></h3><p>API changes are applied immediately. If a change isn&#39;t appearing:</p><ul><li>Refresh the page in Lodestone</li><li>Verify the API request returned a <code>200</code> or <code>201</code> success response (not an error that was silently ignored)</li><li>Check that you sent the write request to the correct endpoint with the correct <code>organizationId</code></li></ul><hr><p><em>This is version 1 of the Lodestone API documentation, documenting confirmed platform behavior.</em></p>',45)])])}const m=a(n,[["render",r]]);export{u as __pageData,m as default};
